content.text:
{
  "name": "单路数据流工具",
  "name_en": "Single-Stream Data Utility",
  "manufacturer": "",
  "description": "用于实验中打开数据文件、记录时间区间并运行单路数据流处理的非实体软件组件。它更像是实验数据采集或流式记录辅助程序，而不是直接控制物理仪器的设备。",
  "description_en": "A non-physical software component used in experiments to open data files, record time intervals, and run single-stream data handling. It appears to be a helper for data acquisition or streaming/logging rather than direct control of a physical instrument.",
  "actions": [
    {
      "action_name": "auto-logtime",
      "description": "记录实验的时间区间。",
      "description_en": "Record an experiment time interval."
    },
    {
      "action_name": "auto-open_data_file",
      "description": "打开用于实验数据流的文件。",
      "description_en": "Open a file used for experimental data streaming."
    },
    {
      "action_name": "auto-run",
      "description": "运行单路数据流处理或记录过程。",
      "description_en": "Run the single-stream data processing or logging routine."
    }
  ],
  "tag_hints": [
    "data streaming",
    "experiment logging",
    "data file handling",
    "time interval recording",
    "software utility"
  ]
}

